CREATE TABLE provider_team_mappings(version TEXT NOT NULL,provider_team_id INTEGER NOT NULL,league_code TEXT NOT NULL,canonical_team_id TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('reviewed','pending')),payload TEXT NOT NULL,PRIMARY KEY(version,provider_team_id,league_code));
CREATE TRIGGER provider_mapping_immutable BEFORE UPDATE ON provider_team_mappings BEGIN SELECT RAISE(ABORT,'provider_mapping_immutable'); END;
CREATE TABLE provider_fixture_observations(id TEXT PRIMARY KEY,fixture_id TEXT NOT NULL,occurrence_id TEXT NOT NULL,league_id TEXT NOT NULL,home_id TEXT,away_id TEXT,kickoff_utc TEXT NOT NULL,business_date TEXT NOT NULL,observed_at TEXT NOT NULL,status TEXT NOT NULL,payload TEXT NOT NULL,checksum TEXT NOT NULL);
CREATE INDEX provider_fixture_latest ON provider_fixture_observations(fixture_id,observed_at);
CREATE INDEX provider_fixture_round ON provider_fixture_observations(business_date,observed_at);
CREATE TRIGGER provider_observation_immutable BEFORE UPDATE ON provider_fixture_observations BEGIN SELECT RAISE(ABORT,'provider_observation_immutable'); END;
CREATE TRIGGER provider_observation_no_delete BEFORE DELETE ON provider_fixture_observations BEGIN SELECT RAISE(ABORT,'provider_observation_immutable'); END;
CREATE TABLE provider_enrichment_observations(id TEXT PRIMARY KEY,fixture_id TEXT NOT NULL,route TEXT NOT NULL,available_at TEXT NOT NULL,coverage TEXT NOT NULL,payload TEXT NOT NULL,checksum TEXT NOT NULL);
CREATE INDEX provider_enrichment_fixture ON provider_enrichment_observations(fixture_id,route,available_at);
CREATE TRIGGER provider_enrichment_immutable BEFORE UPDATE ON provider_enrichment_observations BEGIN SELECT RAISE(ABORT,'provider_enrichment_immutable'); END;
CREATE TABLE provider_dataset_versions(version TEXT PRIMARY KEY,base_version TEXT NOT NULL,created_at TEXT NOT NULL,manifest TEXT NOT NULL);
CREATE TABLE live_feature_snapshots(id TEXT PRIMARY KEY,fixture_id TEXT NOT NULL,cutoff_date TEXT NOT NULL,available_at TEXT NOT NULL,schema_version TEXT NOT NULL,dataset_version TEXT NOT NULL,payload TEXT NOT NULL,checksum TEXT NOT NULL);
CREATE TRIGGER live_feature_immutable BEFORE UPDATE ON live_feature_snapshots BEGIN SELECT RAISE(ABORT,'live_feature_immutable'); END;
CREATE TABLE live_prediction_snapshots(id TEXT PRIMARY KEY,fixture_id TEXT NOT NULL,occurrence_id TEXT NOT NULL,observation_id TEXT NOT NULL REFERENCES provider_fixture_observations(id),generated_at TEXT NOT NULL,kickoff_utc TEXT NOT NULL,feature_id TEXT NOT NULL REFERENCES live_feature_snapshots(id),weights_version TEXT NOT NULL,runtime_version TEXT NOT NULL,mode TEXT NOT NULL CHECK(mode='private_research'),payload TEXT NOT NULL,checksum TEXT NOT NULL,CHECK(generated_at<kickoff_utc));
CREATE INDEX live_prediction_fixture ON live_prediction_snapshots(fixture_id,generated_at);
CREATE TRIGGER live_prediction_immutable BEFORE UPDATE ON live_prediction_snapshots BEGIN SELECT RAISE(ABORT,'live_prediction_immutable'); END;
CREATE TRIGGER live_prediction_no_delete BEFORE DELETE ON live_prediction_snapshots BEGIN SELECT RAISE(ABORT,'live_prediction_immutable'); END;
CREATE TABLE live_match_details(id TEXT PRIMARY KEY,fixture_id TEXT NOT NULL,created_at TEXT NOT NULL,dataset_version TEXT NOT NULL,payload TEXT NOT NULL,checksum TEXT NOT NULL);
CREATE INDEX live_details_latest ON live_match_details(fixture_id,created_at);
CREATE TRIGGER live_detail_immutable BEFORE UPDATE ON live_match_details BEGIN SELECT RAISE(ABORT,'live_detail_immutable'); END;
CREATE TABLE live_daily_reports(id TEXT PRIMARY KEY,business_date TEXT NOT NULL,generated_at TEXT NOT NULL,policy_version TEXT NOT NULL,payload TEXT NOT NULL,checksum TEXT NOT NULL);
CREATE INDEX live_report_latest ON live_daily_reports(business_date,generated_at);
CREATE TRIGGER live_report_immutable BEFORE UPDATE ON live_daily_reports BEGIN SELECT RAISE(ABORT,'live_report_immutable'); END;
CREATE TABLE live_evaluation_revisions(id TEXT PRIMARY KEY,subject_id TEXT NOT NULL,outcome_version TEXT NOT NULL,evaluated_at TEXT NOT NULL,payload TEXT NOT NULL,checksum TEXT NOT NULL);
CREATE TRIGGER live_evaluation_immutable BEFORE UPDATE ON live_evaluation_revisions BEGIN SELECT RAISE(ABORT,'live_evaluation_immutable'); END;
